        static::PERIOD_HOURS => abs($interval->h),
        static::PERIOD_MINUTES => abs($interval->i),
        static::PERIOD_SECONDS => $seconds,
    ]);

    $specString = static::PERIOD_PREFIX;

    foreach ($date as $key => $value) {
        $specString .= $value.$key;
    }

